return dialOptions{
	disableRetry:    !envconfig.Retry,
	reqHandshake:    envconfig.RequireHandshake,
	healthCheckFunc: internal.HealthCheckFunc,
	copts: transport.ConnectOptions{
		WriteBufferSize: defaultWriteBufSize,
		ReadBufferSize:  defaultReadBufSize,
	},
	mct: minConnectTimeout,
}

params.source:
if cc.dopts.bs == nil {
	cc.dopts.bs = backoff.NewExponentialBuilder().Build()
}

// defaultBackoffStrategy configures the backoff strategy that's used when the
// init handshake in the RPC is unsuccessful. It's not for the clientconn
// reconnect backoff.
//
// It has the same value as the default grpc.DefaultBackoffConfig.
//
// TODO: make backoff configurable.
var defaultBackoffStrategy = backoff.NewExponentialBuilder().Build()

// dnsResolver watches for the name resolution update for a non-IP target.
type dnsResolver struct {
	freq       time.Duration
	backoff    backoff.Strategy
	retryCount int
	host       string
	port       string
	resolver   netResolver
	ctx        context.Context
	cancel     context.CancelFunc
	cc         resolver.ClientConn
	// rn channel is used by ResolveNow() to force an immediate resolution of the target.
	rn chan struct{}
	t  *time.Timer
	// wg is used to enforce Close() to return after the watcher() goroutine has finished.
	// Otherwise, data race will be possible. [Race Example] in dns_resolver_test we
	// replace the real lookup functions with mocked ones to facilitate testing.
	// If Close() doesn't wait for watcher() goroutine finishes, race detector sometimes
	// will warns lookup (READ the lookup function pointers) inside watcher() goroutine
	// has data race with replaceNetFunc (WRITE the lookup function pointers).
	wg                   sync.WaitGroup
	disableServiceConfig bool
}

params.body:
host, port, err := parseTarget(target.Endpoint, defaultPort)
if err != nil {
	return nil, err
}

// IP address.
if net.ParseIP(host) != nil {
	host, _ = formatIP(host)
	addr := []resolver.Address{{Addr: host + ":" + port}}
	i := &ipResolver{
		cc: cc,
		ip: addr,
		rn: make(chan struct{}, 1),
		q:  make(chan struct{}),
	}
	cc.NewAddress(addr)
	go i.watcher()
	return i, nil
}

// DNS address (non-IP).
ctx, cancel := context.WithCancel(context.Background())
d := &dnsResolver{
	freq:                 b.minFreq,
	backoff:              backoff.NewExponentialBuilder().MaxDelay(b.minFreq).Build(),
	host:                 host,
	port:                 port,
	ctx:                  ctx,
	cancel:               cancel,
	cc:                   cc,
	t:                    time.NewTimer(0),
	rn:                   make(chan struct{}, 1),
	disableServiceConfig: opts.DisableServiceConfig,
}

if target.Authority == "" {
	d.resolver = defaultResolver
} else {
	d.resolver, err = customAuthorityResolver(target.Authority)
	if err != nil {
		return nil, err
	}
}

d.wg.Add(1)
go d.watcher()
return d, nil

