package main

import (
	"fmt"
	"math/rand"
	"testing"
	"time"
)

type Exponential struct {
	MaxDelay      time.Duration
	BaseDelay     time.Duration
	Jitter        float64
	BackoffFactor float64
}

func (bc Exponential) Backoff(retries int) time.Duration {
	if retries == 0 {
		return bc.BaseDelay
	}
	backoff, max := float64(bc.BaseDelay), float64(bc.MaxDelay)
	for backoff < max && retries > 0 {
		backoff *= bc.BackoffFactor
		retries--
	}
	if backoff > max {
		backoff = max
	}
	backoff *= 1 + bc.Jitter*(rand.Float64()*2-1)
	if backoff < 0 {
		return 0
	}
	return time.Duration(backoff)
}

func TestDefault(t *testing.T) {
	// Default values must match old behavior: base 1s, factor 1.6, jitter 0.2, max 120s.
	bc := Exponential{
		MaxDelay:      120 * time.Second,
		BaseDelay:     1 * time.Second,
		Jitter:        0.2,
		BackoffFactor: 1.6,
	}
	if d := bc.Backoff(0); d != time.Second {
		t.Fatalf("Backoff(0) = %v, want %v", d, time.Second)
	}
	if d := bc.Backoff(1); d != time.Second {
		t.Fatalf("Backoff(1) = %v, want %v", d, time.Second)
	}
	// After many retries, delay must be bounded by MaxDelay (with jitter).
	for i := 100; i < 1000; i++ {
		d := bc.Backoff(i)
		if d > 120*time.Second*1.2+time.Second || d <= 0 {
			t.Fatalf("Backoff(%d) = %v, want in (0, 144s]", i, d)
		}
	}
}

func TestCustom(t *testing.T) {
	// Aggressive retry: base 100ms, factor 1.1, no jitter, max 1s.
	bc := Exponential{
		MaxDelay:      1 * time.Second,
		BaseDelay:     100 * time.Millisecond,
		Jitter:        0,
		BackoffFactor: 1.1,
	}
	if d := bc.Backoff(0); d != 100*time.Millisecond {
		t.Fatalf("Backoff(0) = %v, want 100ms", d)
	}
	if d := bc.Backoff(1); d != 100*time.Millisecond {
		t.Fatalf("Backoff(1) = %v, want 100ms", d)
	}
	// 100ms * 1.1^10 ≈ 259ms
	if d := bc.Backoff(10); d != time.Duration(float64(100*time.Millisecond)*(1.1**10)) {
		t.Fatalf("Backoff(10) = %v, want %v", d, time.Duration(float64(100*time.Millisecond)*(1.1**10)))
	}
	// Bounded by max delay.
	if d := bc.Backoff(100); d != time.Second {
		t.Fatalf("Backoff(100) = %v, want 1s", d)
	}
}

func TestZeroBase(t *testing.T) {
	bc := Exponential{MaxDelay: time.Second, BaseDelay: 0, Jitter: 0, BackoffFactor: 1.6}
	if d := bc.Backoff(5); d != 0 {
		t.Fatalf("Backoff(5) = %v, want 0", d)
	}
}

func TestNegativeResult(t *testing.T) {
	// Huge jitter with tiny base can go negative; result must clamp to 0.
	bc := Exponential{MaxDelay: time.Millisecond, BaseDelay: time.Millisecond, Jitter: 10, BackoffFactor: 1.6}
	d := bc.Backoff(1)
	if d < 0 {
		t.Fatalf("Backoff(1) = %v, want >= 0", d)
	}
}

func main() {
	r := rand.New(rand.NewSource(1))
	_ = r
	if err := func() error {
		return nil
	}(); err != nil {
		fmt.Println(err)
	}
}

